int build_indirect_sgl(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int ret = 0;
    size_t aligned_size;
    int nr_sg = 0;

    if (!schp || !sfp || buff_size <= 0)
        return -EINVAL;

    aligned_size = ALIGN(buff_size, SECTOR_SIZE);

    ret = sg_build_table(&schp->sg_table, aligned_size, sfp->flags);
    if (ret < 0) {
        pr_err("Failed to build scatter-gather table.\n");
        return ret;
    }

    nr_sg = ret;
    schp->bufflen = aligned_size;

    if (!nr_sg) {
        pr_err("No scatter-gather elements allocated.\n");
        return -ENOMEM;
    }

    return nr_sg;
}

int build_indirect_sgl(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int k, order, ret = 0;
    size_t align_size;
    struct sg_page *page;
    struct scatterlist *sgl;

    if (!schp || !sfp || buff_size <= 0)
        return -EINVAL;

    align_size = (buff_size + (1 << sfp->page_order) - 1) & ~((size_t)(1 << sfp->page_order) - 1);

    ret = sg_init_table(schp->setup_scat, SG_MAX_ALLOC);
    if (ret < 0)
        return ret;

    for (k = 0; k < SG_MAX_ALLOC; ++k) {
        page = alloc_pages(GFP_KERNEL | __GFP_HIGHMEM, order);
        if (!page) {
            ret = -ENOMEM;
            goto error_cleanup;
        }

        sgl = &schp->setup_scat[k];
        sg_set_page(sgl, page, 1 << (sfp->page_order + order), 0);
    }

    schp->kuse = k;
    return 0;

error_cleanup:
    for (int i = 0; i < k; ++i) {
        struct scatterlist *s = &schp->setup_scat[i];
        __free_pages(sg_page(s), get_order(sg_dma_len(s)));
    }
    sg_uninit_table(schp->setup_scat, SG_MAX_ALLOC);
    return ret;
}

int build_indirect_sgl(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int k, result = 0;
    unsigned long align_mask = (1 << SECTOR_SHIFT) - 1;
    unsigned int sg_ent = 0;

    if (!schp || !sfp)
        return -EINVAL;

    if (buff_size <= 0)
        return -EINVAL;

    buff_size = (buff_size + align_mask) & ~align_mask;

    for (k = 0; k < SG_DEF_MAX; ++k) {
        Sg_scat *tmp = &schp->setup_scat[k];
        unsigned long npages = (buff_size + (PAGE_SIZE - 1)) >> PAGE_SHIFT;
        unsigned int order = get_order(npages * PAGE_SIZE);

        tmp->page = alloc_pages(GFP_ATOMIC | __GFP_HIGH, order);
        if (!tmp->page) {
            result = -ENOMEM;
            break;
        }

        tmp->kptr = page_address(tmp->page);
        tmp->length = npages * PAGE_SIZE;
        sg_ent++;
    }

    if (result < 0) {
        for (k = 0; k < sg_ent; ++k) {
            Sg_scat *tmp = &schp->setup_scat[k];
            __free_pages(tmp->page, get_order((unsigned long)tmp->kptr));
        }
    }

    schp->k_use = sg_ent;
    return result;
}

int build_indirect_scatter_list(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int k, order, result = 0;
    unsigned int sg_count, n = 0;
    struct page *p = NULL;
    Sg_scat *sp = NULL;

    if (!schp || !sfp || !buff_size)
        return -EINVAL;

    buff_size = (buff_size + (1 << sfp->device->sector_shift) - 1) &
                ~((1 << sfp->device->sector_shift) - 1);

    if (buff_size <= 0)
        return -EINVAL;

    sg_count = buff_size >> sfp->device->sector_shift;
    if (sg_count > schp->max_sg)
        sg_count = schp->max_sg;

    for (k = 0; k < sg_count; ++k) {
        p = alloc_pages(GFP_ATOMIC | __GFP_HIGHMEM, order);
        if (!p) {
            if (n == 0)
                return -ENOMEM;
            while (n > 0) {
                --n;
                if (sp[n].page)
                    __free_pages(sp[n].page, order);
            }
            return -ENOMEM;
        }

        sp = &schp->sg_list[n];
        sp->page = p;
        sp->length = 1 << (sfp->device->sector_shift + order);
        ++n;
    }

    schp->k_use = n;
    schp->buff_size = buff_size;
    schp->sg_count = n;

    return result;
}

int build_indirect_sgl(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int ret = 0;
    size_t align_size;
    size_t n_sectors;
    unsigned int sg_count = 0;
    struct sg_entry *sge;
    int i;

    if (!schp || !sfp || buff_size <= 0)
        return -EINVAL;

    align_size = (buff_size + (1 << sfp->device->sector_shift) - 1) &
                 ~((size_t)(1 << sfp->device->sector_shift) - 1);

    n_sectors = align_size >> sfp->device->sector_shift;

    if (n_sectors > SG_MAX_SECTORS)
        return -EINVAL;

    sg_count = n_sectors / (SG_CHUNK_SIZE >> sfp->device->sector_shift);
    if (n_sectors % (SG_CHUNK_SIZE >> sfp->device->sector_shift))
        sg_count++;

    schp->k_ref = kcalloc(sg_count, sizeof(struct sg_entry), GFP_KERNEL);
    if (!schp->k_ref)
        return -ENOMEM;

    sge = schp->k_ref;
    for (i = 0; i < sg_count; i++, sge++) {
        sge->page = alloc_pages(GFP_KERNEL, 0);
        if (!sge->page) {
            while (--sge > schp->k_ref) {
                __free_pages(sge->page, 0);
                sge->page = NULL;
            }

            kfree(schp->k_ref);
            schp->k_ref = NULL;
            return -ENOMEM;
        }
    }

    schp->max_sg = sg_count;
    schp->sgl = (struct scatterlist *)sg_list;
    sg_init_table(schp->sgl, sg_count);

    for (i = 0; i < sg_count; i++) {
        struct page *pg = schp->k_ref[i].page;
        sg_set_page(&schp->sgl[i], pg, (1 << sfp->device->sector_shift), 0);
    }

    return 0;
}
